<script setup lang="ts">
import {displayText} from '../api'
import {computed,onMounted,ref} from 'vue'
import {api,label,time,type Run,type Incident} from '../api'
import {useSituation,type MapTask} from '../situation'
import {useExecution,executionTypes,executionStatuses,resourceTypes,executionIcon,type ExecutionTask,type ExecutionType,type ExecutionStatus} from '../execution'
import ExecutionTaskDetail from './ExecutionTaskDetail.vue'
import Icon from './Icon.vue'
const props=defineProps<{runs:Run[];mapTasks:MapTask[];incidents:Incident[]}>()
const emit=defineEmits<{'open-run':[run:Run];'open-run-id':[id:string];'open-map-task':[task:MapTask];'show-map':[task:ExecutionTask];'show-event':[id:string];'show-device':[id:string];'new-analysis':[]}>()
const {tasks,resources,failure,loading,selected,selectedId,select,refresh,upsert}=useExecution(),situation=useSituation()
const activeTab=ref<'tasks'|'resources'|'history'>('tasks'),query=ref(''),statusFilter=ref('all'),typeFilter=ref('all'),showCreate=ref(false),creating=ref(false),createError=ref('')
const title=ref(''),incidentId=ref(''),taskType=ref<ExecutionType>('aerial_inspection'),priority=ref<'high'|'medium'|'low'>('medium')
const availableIncidents=computed(()=>situation.data.value?.incidents||props.incidents)
const filteredTasks=computed(()=>tasks.value.filter(task=>(statusFilter.value==='all'||task.status===statusFilter.value)&&(typeFilter.value==='all'||task.task_type===typeFilter.value)&&`${task.code} ${task.title} ${task.incident_title} ${task.target_building_name} ${task.resource_code||''}`.toLowerCase().includes(query.value.trim().toLowerCase())))
const counts=computed(()=>({all:tasks.value.length,pending:tasks.value.filter(t=>t.status==='pending').length,dispatching:tasks.value.filter(t=>t.status==='dispatching').length,running:tasks.value.filter(t=>t.status==='running').length,completed:tasks.value.filter(t=>t.status==='completed').length,abnormal:tasks.value.filter(t=>['failed','cancelled'].includes(t.status)).length}))
const oldRuns=computed(()=>props.runs.filter(run=>`${run.id} ${run.instruction}`.toLowerCase().includes(query.value.toLowerCase())))
const oldMapTasks=computed(()=>props.mapTasks.filter(task=>`${task.id} ${task.instruction}`.toLowerCase().includes(query.value.toLowerCase())))
const priorityLabel=(value:string)=>({high:'高',medium:'中',low:'低'} as Record<string,string>)[value]||value
function createForm(){showCreate.value=true;createError.value='';incidentId.value=availableIncidents.value[0]?.id||'';title.value='';taskType.value='aerial_inspection';priority.value='medium'}
async function create(){if(creating.value||!title.value.trim()||!incidentId.value)return;creating.value=true;createError.value='';try{const task=await api<ExecutionTask>('/execution-tasks',{title:title.value.trim(),incident_id:incidentId.value,task_type:taskType.value,priority:priority.value});upsert(task);select(task.id);showCreate.value=false;activeTab.value='tasks';query.value='';statusFilter.value='all';typeFilter.value='all';void refresh()}catch(e){createError.value=(e as Error).message}finally{creating.value=false}}
function openTask(task:ExecutionTask){select(task.id);activeTab.value='tasks'}
function openResourceTask(id:string){select(id);activeTab.value='tasks';void refresh()}
onMounted(()=>{void refresh();void situation.refresh(true)})
</script>
<template>
 <div class="task-center">
  <header class="execution-page-heading"><div><span class="eyebrow">SKYDOME · MISSION CONTROL</span><h2>任务指挥中心</h2><p>从风险证据到协同执行，让每一步有记录、有结果。</p></div><div class="execution-action-row"><span class="demo-badge">模拟执行</span><button class="outline-button" :disabled="loading" @click="refresh"><Icon name="refresh" :size="15"/>刷新</button><button class="primary-button" @click="createForm"><Icon name="plus" :size="16"/>创建执行任务</button></div></header>
  <div v-if="failure" class="execution-error" role="alert">{{displayText(failure)}} <button class="text-button" @click="refresh">重试连接</button></div>
  <div class="execution-stat-grid"><div><span>全部任务</span><strong>{{counts.all}}</strong><small>统一执行任务数据</small></div><div><span>待执行</span><strong>{{counts.pending}}</strong><small>另有 {{counts.dispatching}} 项派发中</small></div><div><span>执行中</span><strong class="aqua">{{counts.running}}</strong><small>空天地模拟协同</small></div><div><span>已完成</span><strong class="execution-green">{{counts.completed}}</strong><small>结果仍需人工复核</small></div><div><span>异常 / 取消</span><strong class="amber">{{counts.abnormal}}</strong><small>失败与已取消任务</small></div></div>
  <div class="execution-tabs" role="tablist" aria-label="任务中心视图"><button role="tab" :aria-selected="activeTab==='tasks'" :class="{active:activeTab==='tasks'}" @click="activeTab='tasks'"><Icon name="task" :size="16"/>执行任务 <span>{{tasks.length}}</span></button><button role="tab" :aria-selected="activeTab==='resources'" :class="{active:activeTab==='resources'}" @click="activeTab='resources'"><Icon name="flow" :size="16"/>协同资源 <span>{{resources.length}}</span></button><button role="tab" :aria-selected="activeTab==='history'" :class="{active:activeTab==='history'}" @click="activeTab='history'"><Icon name="clock" :size="16"/>历史分析</button></div>
  <form v-if="showCreate" class="execution-create" @submit.prevent="create"><div class="execution-section-heading"><h3>创建 模拟 执行任务</h3><button type="button" class="icon-button" aria-label="关闭创建任务" :disabled="creating" @click="showCreate=false"><Icon name="close" :size="18"/></button></div><p>从已有事件绑定建筑及设备；任务创建后仍需选择资源并确认启动。</p><div class="execution-form-grid"><label class="wide">任务名称<input v-model="title" aria-label="执行任务名称" placeholder="例如：实训基地温度异常现场核查" required maxlength="120" :disabled="creating"/></label><label class="wide">关联风险事件<select v-model="incidentId" aria-label="执行任务关联事件" required :disabled="creating"><option v-for="event in availableIncidents" :key="event.id" :value="event.id">{{displayText(event.title)}} · {{time(event.triggered_at,true)}}</option></select></label><label>任务类型<select v-model="taskType" aria-label="执行任务类型" :disabled="creating"><option v-for="(name,type) in executionTypes" :key="type" :value="type">{{name}}</option></select></label><label>任务优先级<select v-model="priority" aria-label="执行任务优先级" :disabled="creating"><option value="high">高优先级</option><option value="medium">中优先级</option><option value="low">低优先级</option></select></label></div><p v-if="createError" class="execution-error" role="alert">{{displayText(createError)}}</p><div class="execution-action-row"><button type="submit" class="primary-button" :disabled="creating||!title.trim()||!incidentId">{{creating?'正在创建…':'保存待执行任务'}}</button><button type="button" class="text-button" :disabled="creating" @click="showCreate=false">取消</button></div></form>
  <template v-if="activeTab==='tasks'">
   <div class="execution-filters"><label class="execution-search"><Icon name="search" :size="16"/><input v-model="query" aria-label="搜索执行任务" placeholder="搜索任务、事件、建筑或资源"/></label><select v-model="statusFilter" aria-label="筛选执行任务状态"><option value="all">全部状态</option><option v-for="(name,status) in executionStatuses" :key="status" :value="status">{{name}}</option></select><select v-model="typeFilter" aria-label="筛选执行任务类型"><option value="all">全部类型</option><option v-for="(name,type) in executionTypes" :key="type" :value="type">{{name}}</option></select></div>
   <div class="execution-layout" :class="{'has-detail':!!selected}"><section class="execution-task-list" aria-label="执行任务列表"><div class="execution-list-caption"><span>{{filteredTasks.length}} 个任务</span><span>后端持久化 · 自动同步</span></div><button v-for="task in filteredTasks" :key="task.id" class="execution-task-card" :class="{selected:selectedId===task.id}" @click="openTask(task)"><div class="execution-task-top"><span class="execution-type-icon"><Icon :name="executionIcon(task.task_type)" :size="21"/></span><div><small>{{task.code}} · {{executionTypes[task.task_type]}}</small><h3>{{displayText(task.title)}}</h3></div><span class="execution-status" :class="task.status">{{executionStatuses[task.status]}}</span></div><div class="execution-card-meta"><span><Icon name="pin" :size="13"/>{{displayText(task.target_building_name)}}</span><span class="execution-priority" :class="task.priority">{{priorityLabel(task.priority)}}优先级</span><span>{{task.resource_code||'资源待分配'}}</span></div><div class="execution-card-progress"><progress :value="task.progress" max="100"></progress><strong>{{Math.round(task.progress)}}%</strong></div><footer><span>{{displayText(task.source_label)}}</span><span>{{time(task.created_at,true)}}</span></footer></button><div v-if="!filteredTasks.length" class="execution-empty"><Icon name="task" :size="34"/><h3>{{tasks.length?'没有符合筛选的任务':'尚无执行任务'}}</h3><p>可手动创建，也可从已完成的规则核查结果生成关联任务。</p><button class="outline-button" @click="createForm">创建首个执行任务</button></div></section><ExecutionTaskDetail v-if="selected" :task="selected" @close="select('')" @show-map="emit('show-map',$event)" @show-event="emit('show-event',$event)" @show-device="emit('show-device',$event)" @show-run="emit('open-run-id',$event)" @open-task="openTask"/></div>
   <p v-if="selectedId&&!selected&&!loading" class="execution-error">所选任务未找到。<button class="text-button" @click="select('')">清除失效选择</button></p>
  </template>
  <section v-else-if="activeTab==='resources'" class="execution-resources"><div class="execution-section-heading"><div><h3>空天地协同资源</h3><p>资源占用与已有巡检共用状态；未连接真实控制链路。</p></div><span>{{resources.filter(r=>r.status==='available').length}} / {{resources.length}} 可用</span></div><div class="execution-resource-grid"><article v-for="resource in resources" :key="resource.id" class="execution-resource-card" :class="resource.type"><div class="execution-resource-visual"><Icon :name="executionIcon(resource.type)" :size="42"/><span>{{resourceTypes[resource.type]}}</span></div><div class="execution-resource-card-heading"><h3>{{resource.code}}</h3><span class="execution-status" :class="resource.status">{{label(resource.status)}}</span></div><p>{{displayText(resource.name)}}</p><dl><div><dt>覆盖 / 位置</dt><dd>{{displayText(resource.area)}}</dd></div><div><dt>在线状态</dt><dd>{{resource.online?'在线（模拟）':'离线'}}</dd></div><div><dt>电量</dt><dd>{{resource.battery===null?'不适用':resource.battery+'%'}}</dd></div><div><dt>当前任务</dt><dd><button v-if="resource.current_task_id&&tasks.some(task=>task.id===resource.current_task_id)" class="text-button" @click="openResourceTask(resource.current_task_id)">{{resource.current_task_code||resource.current_task_id}} ↗</button><span v-else>{{resource.current_task_code||'待命'}}</span></dd></div></dl><div class="execution-capabilities"><span v-for="capability in resource.capabilities" :key="capability">{{displayText(capability)}}</span></div><small>{{resource.device_id?`稳定设备 ID：${resource.device_id}`:'模拟资源，无实际遥感影像接入'}}</small><p v-if="resource.reason" class="execution-muted">{{resource.reason}}</p></article></div></section>
  <section v-else class="execution-history"><div class="execution-section-heading"><div><h3>历史核查与地图分析</h3><p>保留 DAY 01—03 的分析记录，与执行任务分开管理。</p></div><button class="outline-button" @click="emit('new-analysis')">新建基础核查</button></div><label class="execution-search"><Icon name="search" :size="16"/><input v-model="query" aria-label="搜索历史分析" placeholder="搜索历史指令或编号"/></label><h4>规则核查记录 · {{oldRuns.length}}</h4><button v-for="run in oldRuns" :key="run.id" class="execution-history-row" @click="emit('open-run',run)"><Icon name="file" :size="20"/><span><strong>{{displayText(run.instruction)}}</strong><small>{{run.id}} · {{time(run.created_at,true)}}</small></span><span class="status-badge" :class="run.status">{{label(run.status)}}</span><Icon name="chevron" :size="14"/></button><p v-if="!oldRuns.length" class="execution-muted">暂无符合条件的核查记录。</p><h4>地图关联分析 · {{oldMapTasks.length}}</h4><button v-for="task in oldMapTasks" :key="task.id" class="execution-history-row" @click="emit('open-map-task',task)"><Icon name="map" :size="20"/><span><strong>{{displayText(task.instruction)}}</strong><small>{{task.id}} · {{time(task.created_at,true)}}</small></span><span>{{label(task.status)}}</span></button><p v-if="!oldMapTasks.length" class="execution-muted">暂无符合条件的地图关联分析。</p></section>
 </div>
</template>
